import React from 'react';
import Svg, { Circle, Ellipse, G, Line, Path, Rect } from 'react-native-svg';
import { classify } from '../engine/classify';

// 食材アイコン。有名どころは専用、無名はカテゴリ標準アイコンを名前ハッシュで固定割り当て
// （同じ食材は毎回同じ絵になる）。全てコードで描画＝画像素材・ライセンス不要。

function hashStr(s: string): number {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
  return h;
}

const FISH_COLORS = ['#8FB4C4', '#9DB39A', '#B6A9C0', '#A8B0B8'];
const FRUIT_COLORS = ['#E0524B', '#E8A33C', '#C44D6E', '#7FB04F', '#8E6FB0'];
const VEG_COLORS = ['#8FBF6B', '#A8CB8C', '#C9D98F'];

