  卵: 'egg', 豆腐: 'tofu', 厚揚げ: 'tofu', 油揚げ: 'tofu', 高野豆腐: 'tofu', 納豆: 'natto',
  牛乳: 'milk', ヨーグルト: 'yogurt', 豆乳: 'soymilk', チーズ: 'cheese', バター: 'cheese', 生クリーム: 'milk',
