  ウインナー: 'sausage', ソーセージ: 'sausage',
  ごはん: 'rice', 米: 'ricebag', 食パン: 'bread', ロールパン: 'bread', パスタ: 'noodle', うどん: 'udon', そば: 'soba', 中華麺: 'yakisoba',
  りんご: 'fruit', バナナ: 'fruit', みかん: 'fruit', オレンジ: 'fruit', ぶどう: 'fruit', いちご: 'fruit',
  メロン: 'fruit', すいか: 'fruit', もも: 'fruit', パイナップル: 'fruit', レモン: 'fruit', さくらんぼ: 'fruit',
