export function FoodIcon({ name, size = 32 }: { name: string; size?: number }) {
  const { key, color } = resolve(name);
  return (
    <Svg width={size} height={size} viewBox="0 0 40 40">
      <Shape k={key} color={color} />
    </Svg>
  );
}
